public record Order(string Customer, decimal Amount, bool Cancelled);

public static class OrderStats
{
    // Total por cliente sin contar los pedidos cancelados.
    // El cliente no distingue mayúsculas: "ACME" y "acme" son el mismo cliente.
    // La clave del diccionario es el nombre tal como aparece en el primer pedido no cancelado de ese cliente.
    // Los clientes sin pedidos no cancelados no aparecen.
    public static Dictionary<string, decimal> TotalsByCustomer(IEnumerable<Order> orders)
    {
        return orders
            .GroupBy(o => o.Customer)
            .ToDictionary(g => g.Key, g => g.Sum(o => o.Amount));
    }
}
