using System.Text;
public static class Csv {
  public static List<string> ParseLine(string line) {
    var r = new List<string>(); var sb = new StringBuilder(); bool q = false;
    for (int i = 0; i < line.Length; i++) {
      char c = line[i];
      if (q) {
        if (c == '"') { if (i + 1 < line.Length && line[i + 1] == '"') { sb.Append('"'); i++; } else q = false; }
        else sb.Append(c);
      } else if (c == '"') q = true;
      else if (c == ',') { r.Add(sb.ToString()); sb.Clear(); }
      else sb.Append(c);
    }
    if (q) throw new FormatException("unterminated quote");
    r.Add(sb.ToString()); return r;
  }
}
